import unittest

from ledger import budget, report
from tests.helpers import SAMPLE, journal


class Budget(unittest.TestCase):
    def test_variance(self):
        plan = budget.load_csv("account,month,amount\n5000,2026-01,1000.00\n")
        self.assertEqual(report.variance(journal(*SAMPLE), plan, "2026-01"), [("5000", "Rent", 100000, 120000, 20000)])

    def test_a_month_twice_is_refused(self):
        with self.assertRaises(ValueError):
            budget.load_csv("account,month,amount\n5000,2026-01,1.00\n5000,2026-01,2.00\n")


if __name__ == "__main__":
    unittest.main()
